=== studio theme.css (design system reference) ===
557 studio/src/styles/theme.css
:root {
  color-scheme: dark;
  --studio-bg-1: #131722;
  --studio-bg-2: #0b0d13;
  --studio-text: #f1f5f9;
  --studio-muted: #94a3b8;
  --studio-indigo: #818cf8;
  --studio-indigo-strong: #6366f1;
  --studio-green: #34d399;
  --studio-amber: #fbbf24;
  --studio-red: #f87171;
  --studio-surface: rgba(255, 255, 255, 0.03);
  --studio-surface-strong: rgba(255, 255, 255, 0.05);
  --studio-border: rgba(255, 255, 255, 0.08);
  --studio-radius: 12px;
  --studio-font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial,
    sans-serif;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  font-family: var(--studio-font);
}

.studio-app {
  min-height: 100vh;
  padding: 16px 20px 32px;
  background: radial-gradient(circle at 15% 15%, var(--studio-bg-1) 0%, var(--studio-bg-2) 100%);
  color: var(--studio-text);
  font-family: var(--studio-font);
}

/* ------------------------------------------------------------------ */
/* Header + status pills                                              */
/* ------------------------------------------------------------------ */
.studio-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 18px;
  background: var(--studio-surface);
  border: 1px solid var(--studio-border);
  border-radius: var(--studio-radius);
  margin-bottom: 18px;
  gap: 16px;
  flex-wrap: wrap;
}

.studio-header__title {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.studio-header__title span {
  opacity: 0.5;
  font-size: 1rem;
  font-weight: 400;
}


